<?php

namespace tttran\viet_qr_generator;

/**
 * Library version, managed by scripts/release.sh (Maven-like release flow).
 *
 * During development the version carries a -SNAPSHOT suffix. The release
 * script replaces it with the release version for the tagged commit, then
 * bumps it to the next -SNAPSHOT afterwards. Do not edit it by hand.
 */
final class Version
{
    const VERSION = '0.9-SNAPSHOT';
}
